static inline u32 *ethtool_rxfh_context_indir(struct ethtool_rxfh_context *ctx) /* <=== ethtool_rxfh_context_indir */ 
{
	return (u32 *)(ctx->data + ALIGN(ctx->priv_size, sizeof(u32)));
}

static inline u32 ethtool_rxfh_indir_default(u32 index, u32 n_rx_rings) /* <=== ethtool_rxfh_indir_default */ 
{
	return index % n_rx_rings;
}

void bnxt_set_dflt_rss_indir_tbl(struct bnxt *bp, /* <=== bnxt_set_dflt_rss_indir_tbl */ 
				 struct ethtool_rxfh_context *rss_ctx)
{
	u16 max_rings, max_entries, pad, i;
	u32 *rss_indir_tbl;

	if (!bp->rx_nr_rings)
		return;

	if (BNXT_CHIP_TYPE_NITRO_A0(bp))
		max_rings = bp->rx_nr_rings - 1;
	else
		max_rings = bp->rx_nr_rings;

	max_entries = bnxt_get_rxfh_indir_size(bp->dev);
	if (rss_ctx)
		rss_indir_tbl = ethtool_rxfh_context_indir(rss_ctx);
	else
		rss_indir_tbl = &bp->rss_indir_tbl[0];

	for (i = 0; i < max_entries; i++)
		rss_indir_tbl[i] = ethtool_rxfh_indir_default(i, max_rings);

	pad = bp->rss_indir_tbl_entries - max_entries;
	if (pad)
		memset(&rss_indir_tbl[i], 0, pad * sizeof(*rss_indir_tbl));
}

__attribute__((weak,unused,section(".text.nolibc_memset"))) /* <=== memset */ 
void *memset(void *dst, int b, size_t len)
{
	char *p = dst;

	while (len--) {
		/* prevent gcc from recognizing memset() here */
		__asm__ volatile("");
		*(p++) = b;
	}
	return dst;
}

static int bnxt_get_func_stat_ctxs(struct bnxt *bp) /* <=== bnxt_get_func_stat_ctxs */ 
{
	return bp->cp_nr_rings + bnxt_get_ulp_stat_ctxs(bp);
}

u32 bnxt_get_rxfh_indir_size(struct net_device *dev) /* <=== bnxt_get_rxfh_indir_size */ 
{
	struct bnxt *bp = netdev_priv(dev);

	if (bp->flags & BNXT_FLAG_CHIP_P5_PLUS)
		return bnxt_get_nr_rss_ctxs(bp, bp->rx_nr_rings) *
		       BNXT_RSS_TABLE_ENTRIES_P5;
	return HW_HASH_INDEX_SIZE;
}

int bnxt_get_ulp_stat_ctxs(struct bnxt *bp) /* <=== bnxt_get_ulp_stat_ctxs */ 
{
	if (bp->edev)
		return bp->edev->ulp_num_ctxs;
	return 0;
}

static inline bool netif_is_rxfh_configured(const struct net_device *dev) /* <=== netif_is_rxfh_configured */ 
{
	return dev->priv_flags & IFF_RXFH_CONFIGURED;
}

static int bnxt_get_total_vnics(struct bnxt *bp, int rx_rings) /* <=== bnxt_get_total_vnics */ 
{
	if (bp->flags & BNXT_FLAG_RFS) {
		if (BNXT_SUPPORTS_NTUPLE_VNIC(bp))
			return 2 + bp->num_rss_ctx;
		if (!(bp->flags & BNXT_FLAG_CHIP_P5_PLUS))
			return rx_rings + 1;
	}
	return 1;
}

static void bnxt_check_rss_tbl_no_rmgr(struct bnxt *bp) /* <=== bnxt_check_rss_tbl_no_rmgr */ 
{
	struct bnxt_hw_resc *hw_resc = &bp->hw_resc;

	/* The RSS map is valid for RX rings set to resv_rx_rings */
	if (hw_resc->resv_rx_rings != bp->rx_nr_rings) {
		hw_resc->resv_rx_rings = bp->rx_nr_rings;
		if (!netif_is_rxfh_configured(bp->dev))
			bnxt_set_dflt_rss_indir_tbl(bp, NULL);
	}
}

